func _wire_win_popup_border_touch(popup_slot: Node, payout_cents: int) -> void:
	if payout_cents <= 0:
		return
	if not popup_slot.has_signal("win_popup_border_touched"):
		return
	var handler := Callable(self, "_on_win_popup_border_touched").bind(payout_cents)
	if popup_slot.is_connected("win_popup_border_touched", handler):
		popup_slot.disconnect("win_popup_border_touched", handler)
	popup_slot.connect("win_popup_border_touched", handler, CONNECT_ONE_SHOT)


func _on_win_popup_border_touched(payout_cents: int, _emitted_cents: int = 0) -> void:
	var amount := payout_cents if payout_cents > 0 else _emitted_cents
	if amount <= 0:
		return
	emit_signal("winnings_popup_border_touched", {"payout_cents": amount})

